/**
 * Repo Contract Interop Demo
 *
 * This example demonstrates cross-chain lending using the RepoContract with shadow accounts:
 * 1. Deploy RepoContract on chain A
 * 2. Deploy and register ERC20 tokens (lend token + collateral token)
 * 3. Lender creates an offer on chain A
 * 4. Borrower from chain B accepts the offer using shadow account
 * 5. Borrower repays the loan using shadow account
 *
 * Usage:
 *   npx ts-node index.ts
 *
 * Required environment variables:
 *   - PRIVATE_KEY: Private key for the wallet
 *   - L2_RPC_URL: RPC URL for chain A (where repo contract is deployed)
 *   - L2_RPC_URL_SECOND: RPC URL for chain B (borrower's chain)
 */

import { ethers } from 'ethers';
import {
  sendBundle,
  waitForBundleFinalization,
  waitUntilRootAvailable,
  executeBundle,
  BundleBuilder,
  CallBuilder,
  computeAssetId,
  buildBridgeCalldata,
  L2_ASSET_ROUTER_ADDRESS,
  L2_NATIVE_TOKEN_VAULT_ADDRESS,
  L2_INTEROP_HANDLER_ADDRESS,
  NativeTokenVaultAbi,
  ERC20Abi,
  extractBundlesFromReceipt,
  finalizeAndExecuteBridgeBundle,
  getBridgedTokenAddress,
} from 'interop-sdk';

// SimpleERC20 bytecode (constructor takes uint256 initialSupply)
const TOKEN_BYTECODE =
  '';

// RepoContract bytecode (constructor takes address _admin)
const REPO_CONTRACT_BYTECODE =
  '';

// RepoContract ABI (relevant functions)
const RepoContractAbi = [
  'function createOffer(address _lendToken, uint256 _lendAmount, address _collateralToken, uint256 _collateralAmount, uint256 _duration, uint256 _lenderChainId, address _lenderRefundAddress, uint256 _lenderFee) returns (uint256 offerId)',
  'function acceptOffer(uint256 _offerId, uint256 _borrowerChainId, address _borrowerRefundAddress)',
  'function repayLoan(uint256 _offerId)',
  'function setUnbundlerAddress(address _unbundlerAddress)',
  'function offers(uint256) view returns (uint256 offerId, address lender, address borrower, address lenderRefundAddress, address borrowerRefundAddress, uint256 lenderChainId, uint256 borrowerChainId, address lendToken, uint256 lendAmount, address collateralToken, uint256 collateralAmount, uint256 duration, uint256 startTime, uint256 endTime, uint256 lenderFee, uint8 status)',
  'function calculateRepaymentAmount(uint256 _offerId) view returns (uint256)',
  'function getOpenOffers() view returns (tuple(uint256 offerId, address lender, address borrower, address lenderRefundAddress, address borrowerRefundAddress, uint256 lenderChainId, uint256 borrowerChainId, address lendToken, uint256 lendAmount, address collateralToken, uint256 collateralAmount, uint256 duration, uint256 startTime, uint256 endTime, uint256 lenderFee, uint8 status)[])',
  'event OfferCreated(uint256 indexed offerId, address indexed lender, uint256 lenderChainId)',
  'event OfferAccepted(uint256 indexed offerId, address indexed borrower, uint256 borrowerChainId)',
  'event LoanRepaid(uint256 indexed offerId)',
];

// InteropHandler ABI for getting shadow account address
const InteropHandlerAbi = [
  'function getShadowAccountAddress(uint256 _ownerChainId, address _ownerAddress) view returns (address)',
];

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing env var: ${name}`);
  }
  return value;
}

async function deployContract(
  wallet: ethers.Wallet,
  bytecode: string,
  constructorArgs: string,
  name: string
): Promise<string> {
  console.log(`Deploying ${name}...`);
  const deployData = bytecode + constructorArgs.substring(2);
  const deployTx = await wallet.sendTransaction({
    data: deployData,
    gasLimit: 10_000_000n,
    gasPrice: 1_000_000_000n,
  });
  console.log(`Deploy tx hash: ${deployTx.hash}`);
  const receipt = await deployTx.wait();
  const contractAddress = receipt!.contractAddress!;
  console.log(`${name} deployed at: ${contractAddress}`);
  return contractAddress;
}

async function deployToken(wallet: ethers.Wallet, initialSupply: bigint): Promise<string> {
  const constructorArgs = ethers.AbiCoder.defaultAbiCoder().encode(['uint256'], [initialSupply]);
  return deployContract(wallet, TOKEN_BYTECODE, constructorArgs, 'ERC20 Token');
}

async function registerToken(wallet: ethers.Wallet, tokenAddress: string): Promise<void> {
  console.log('Registering token with Native Token Vault...');
  const nativeTokenVault = new ethers.Contract(
    L2_NATIVE_TOKEN_VAULT_ADDRESS,
    [...NativeTokenVaultAbi, 'function ensureTokenIsRegistered(address _nativeToken) returns (bytes32)'],
    wallet
  );
  const registerTx = await nativeTokenVault.ensureTokenIsRegistered(tokenAddress, {
    gasLimit: 5_000_000n,
    gasPrice: 1_000_000_000n,
  });
  console.log(`Register tx hash: ${registerTx.hash}`);
  await registerTx.wait();
  console.log('Token registered successfully');
}

async function getShadowAccountAddress(
  provider: ethers.Provider,
  ownerChainId: bigint,
  ownerAddress: string
): Promise<string> {
  const interopHandler = new ethers.Contract(L2_INTEROP_HANDLER_ADDRESS, InteropHandlerAbi, provider);
  return await interopHandler.getShadowAccountAddress(ownerChainId, ownerAddress);
}

async function sendAndExecuteBundle(
  sourceWallet: ethers.Wallet,
  sourceProvider: ethers.Provider,
  destWallet: ethers.Wallet,
  destProvider: ethers.Provider,
  bundle: BundleBuilder,
  description: string
): Promise<ethers.TransactionReceipt> {
  console.log(`\n--- ${description} ---`);

  // Send bundle
  console.log('Sending bundle...');
  const handle = await sendBundle(sourceWallet, bundle);
  console.log('Bundle hash:', handle.bundleHash);
  console.log('Tx hash:', handle.txHash);

  // Wait for finalization
  console.log('Waiting for finalization...');
  const finalizationInfo = await waitForBundleFinalization(sourceProvider, handle);
  console.log('Bundle finalized! Batch:', finalizationInfo.expectedRoot.batchNumber);

  // Wait for root availability
  console.log('Waiting for root availability on destination...');
  await waitUntilRootAvailable(destProvider, finalizationInfo.expectedRoot);
  console.log('Root available!');

  // Execute bundle
  console.log('Executing bundle...');
  const receipt = await executeBundle(destWallet, finalizationInfo, {
    gasLimit: 10_000_000n,
    gasPrice: 1_000_000_000n,
  });
  console.log('Execute tx hash:', receipt.hash);
  console.log('Execute status:', receipt.status === 1 ? 'Success' : 'Failed');

  return receipt;
}

async function main() {
  const PRIVATE_KEY = requireEnv('PRIVATE_KEY');
  const L2_RPC_URL = requireEnv('L2_RPC_URL');
  const L2_RPC_URL_SECOND = requireEnv('L2_RPC_URL_SECOND');

  // Setup providers
  const providerA = new ethers.JsonRpcProvider(L2_RPC_URL);
  const providerB = new ethers.JsonRpcProvider(L2_RPC_URL_SECOND);

  // Setup wallets (same key on both chains)
  const walletA = new ethers.Wallet(PRIVATE_KEY, providerA);
  const walletB = new ethers.Wallet(PRIVATE_KEY, providerB);

  console.log('Wallet address:', walletA.address);

  // Get chain IDs
  const chainAId = (await providerA.getNetwork()).chainId;
  const chainBId = (await providerB.getNetwork()).chainId;
  console.log('Chain A ID:', chainAId, '(RepoContract chain)');
  console.log('Chain B ID:', chainBId, '(Borrower chain)');

  // =================================================================
  // STEP 1: Deploy RepoContract on Chain A
  // =================================================================
  console.log('\n========================================');
  console.log('STEP 1: DEPLOY REPO CONTRACT ON CHAIN A');
  console.log('========================================');

  const adminConstructorArgs = ethers.AbiCoder.defaultAbiCoder().encode(['address'], [walletA.address]);
  const repoContractAddress = await deployContract(
    walletA,
    REPO_CONTRACT_BYTECODE,
    adminConstructorArgs,
    'RepoContract'
  );

  const repoContract = new ethers.Contract(repoContractAddress, RepoContractAbi, walletA);

  // Set unbundler address for cross-chain transfers
  console.log('Setting unbundler address...');
  const setUnbundlerTx = await repoContract.setUnbundlerAddress(walletA.address, {
    gasLimit: 100_000n,
    gasPrice: 1_000_000_000n,
  });
  await setUnbundlerTx.wait();
  console.log('Unbundler address set');

  // =================================================================
  // STEP 2: Deploy and Register ERC20 Tokens on Chain A
  // =================================================================
  console.log('\n========================================');
  console.log('STEP 2: DEPLOY AND REGISTER TOKENS');
  console.log('========================================');

  const initialSupply = ethers.parseUnits('1000000', 18);

  // Deploy lend token
  console.log('\n--- Deploying Lend Token ---');
  const lendTokenAddress = await deployToken(walletA, initialSupply);
  await registerToken(walletA, lendTokenAddress);
  const lendToken = new ethers.Contract(lendTokenAddress, ERC20Abi, walletA);

  // Deploy collateral token
  console.log('\n--- Deploying Collateral Token ---');
  const collateralTokenAddress = await deployToken(walletA, initialSupply);
  await registerToken(walletA, collateralTokenAddress);
  const collateralToken = new ethers.Contract(collateralTokenAddress, ERC20Abi, walletA);

  // =================================================================
  // STEP 3: Lender Creates Offer
  // =================================================================
  console.log('\n========================================');
  console.log('STEP 3: LENDER CREATES OFFER');
  console.log('========================================');

  const lendAmount = ethers.parseUnits('100', 18);
  const collateralAmount = ethers.parseUnits('150', 18);
  const duration = 3600n; // 1 hour
  // TODO: use non-zero fee.
  const lenderFee = 0n; // 1% fee (100 basis points)

  // Approve lend token to repo contract
  console.log('Approving lend token to RepoContract...');
  const approveLendTx = await lendToken.approve(repoContractAddress, lendAmount, {
    gasLimit: 100_000n,
    gasPrice: 1_000_000_000n,
  });
  await approveLendTx.wait();
  console.log('Lend token approved');

  // Create offer
  console.log('Creating offer...');
  const createOfferTx = await repoContract.createOffer(
    lendTokenAddress, // _lendToken
    lendAmount, // _lendAmount
    collateralTokenAddress, // _collateralToken
    collateralAmount, // _collateralAmount
    duration, // _duration
    chainAId, // _lenderChainId (lender is on chain A)
    walletA.address, // _lenderRefundAddress
    lenderFee, // _lenderFee
    {
      gasLimit: 500_000n,
      gasPrice: 1_000_000_000n,
    }
  );
  const createOfferReceipt = await createOfferTx.wait();
  console.log('Create offer tx:', createOfferTx.hash);

  // Get offer ID from events
  const offerCreatedEvent = createOfferReceipt?.logs?.find(
    (log: any) => log.topics[0] === ethers.id('OfferCreated(uint256,address,uint256)')
  );
  const offerId = offerCreatedEvent ? BigInt(offerCreatedEvent.topics[1]) : 1n;
  console.log('Offer created with ID:', offerId.toString());

  // =================================================================
  // STEP 4: Send Collateral to Borrower's Shadow Account on Chain A
  // =================================================================
  console.log('\n========================================');
  console.log('STEP 4: SEND COLLATERAL TO SHADOW ACCOUNT');
  console.log('========================================');

  // Get borrower's shadow account address on chain A
  const borrowerShadowAccount = await getShadowAccountAddress(providerA, chainBId, walletB.address);
  console.log("Borrower's shadow account on Chain A:", borrowerShadowAccount);

  // Send collateral tokens to shadow account
  console.log('Sending collateral tokens to shadow account...');
  const sendCollateralTx = await collateralToken.transfer(borrowerShadowAccount, collateralAmount, {
    gasLimit: 100_000n,
    gasPrice: 1_000_000_000n,
  });
  await sendCollateralTx.wait();
  console.log('Collateral sent to shadow account');

  // Check shadow account balance
  const shadowCollateralBalance = await collateralToken.balanceOf(borrowerShadowAccount);
  console.log('Shadow account collateral balance:', ethers.formatUnits(shadowCollateralBalance, 18));

  // =================================================================
  // STEP 5: Borrower Accepts Offer Using Shadow Account
  // =================================================================
  console.log('\n========================================');
  console.log('STEP 5: BORROWER ACCEPTS OFFER (SHADOW ACCOUNT)');
  console.log('========================================');

  // Build approve calldata
  const approveCollateralCalldata = collateralToken.interface.encodeFunctionData('approve', [
    repoContractAddress,
    collateralAmount,
  ]);

  // Build acceptOffer calldata
  const acceptOfferCalldata = repoContract.interface.encodeFunctionData('acceptOffer', [
    offerId,
    chainBId, // borrower chain ID
    walletB.address, // borrower refund address
  ]);

  // Build bundle with shadow account calls
  const acceptBundle = new BundleBuilder(chainAId)
    // First call: approve collateral token via shadow account
    .addShadowAccountCall(collateralTokenAddress, approveCollateralCalldata)
    // Second call: accept offer via shadow account
    .addShadowAccountCall(repoContractAddress, acceptOfferCalldata)
    .withUnbundler(walletA.address);

  const acceptExecReceipt = await sendAndExecuteBundle(
    walletB,
    providerB,
    walletA,
    providerA,
    acceptBundle,
    'Accept Offer Bundle'
  );

  // Check offer status
  const offerAfterAccept = await repoContract.offers(offerId);
  console.log('Offer status after accept:', offerAfterAccept.status); // 1 = Active

  // =================================================================
  // STEP 5b: FINALIZE TOKEN BRIDGE TO CHAIN B
  // =================================================================
  console.log('\n--- Finalizing token bridge to Chain B ---');

  // The acceptOffer execution on chain A triggers a token transfer to chain B
  // This creates a new bundle that needs to be finalized and executed on chain B
  const bridgeBundles = extractBundlesFromReceipt(acceptExecReceipt, chainAId);
  console.log(`Found ${bridgeBundles.length} bridge bundle(s) to finalize`);

  if (bridgeBundles.length > 0) {
    for (const bundleInfo of bridgeBundles) {
      console.log(`Finalizing bridge bundle: ${bundleInfo.bundleHandle.bundleHash}`);
      const bridgeReceipt = await finalizeAndExecuteBridgeBundle(
        providerA,
        walletB,
        bundleInfo,
        {
          // gasLimit: 10_000_000n,
          // gasPrice: 1_000_000_000n,
        }
      );
      console.log(`Bridge bundle executed on chain B, tx: ${bridgeReceipt.hash}`);
    }
  }

  // Get the bridged lend token address on chain B
  const lendTokenAddressOnB = await getBridgedTokenAddress(chainAId, lendTokenAddress, providerB);
  console.log('Lend token address on Chain B:', lendTokenAddressOnB);

  // Check borrower received lend tokens on chain B
  const lendTokenOnB = new ethers.Contract(lendTokenAddressOnB, ERC20Abi, providerB);
  const borrowerLendBalance = await lendTokenOnB.balanceOf(walletB.address);
  console.log('Borrower lend token balance on Chain B:', ethers.formatUnits(borrowerLendBalance, 18));

  // =================================================================
  // STEP 6: Bridge Lend Tokens Back to Chain A for Repayment
  // =================================================================
  console.log('\n========================================');
  console.log('STEP 6: BRIDGE LEND TOKENS BACK TO CHAIN A');
  console.log('========================================');

  // Calculate repayment amount
  const repaymentAmount = await repoContract.calculateRepaymentAmount(offerId);
  console.log('Repayment amount:', ethers.formatUnits(repaymentAmount, 18));

  // Get asset ID of lend token (computed from chain A origin)
  const lendTokenAssetId = computeAssetId(chainAId, L2_NATIVE_TOKEN_VAULT_ADDRESS, lendTokenAddress);
  console.log('Lend token asset ID:', lendTokenAssetId);

  // The borrower needs to bridge lend tokens from chain B to chain A (to their shadow account)
  // First approve the NTV on chain B to spend the tokens
  console.log('Approving NTV on chain B to spend lend tokens...');
  const lendTokenOnBWithSigner = new ethers.Contract(lendTokenAddressOnB, ERC20Abi, walletB);
  const approveNtvTx = await lendTokenOnBWithSigner.approve(L2_NATIVE_TOKEN_VAULT_ADDRESS, repaymentAmount, {
    gasLimit: 100_000n,
    gasPrice: 1_000_000_000n,
  });
  await approveNtvTx.wait();
  console.log('NTV approved');

  // Build calldata for bridging tokens via asset router
  const bridgeBackCalldata = buildBridgeCalldata(
    lendTokenAssetId,
    repaymentAmount,
    borrowerShadowAccount, // Send to borrower's shadow account on chain A
    ethers.ZeroAddress
  );

  // Create bundle to bridge tokens from B to A
  const bridgeBackBundle = new BundleBuilder(chainAId)
    .addCall(
      new CallBuilder(L2_ASSET_ROUTER_ADDRESS, bridgeBackCalldata)
        .asIndirectCall(0n)
        .build()
    )
    .withUnbundler(walletA.address);

  await sendAndExecuteBundle(
    walletB,
    providerB,
    walletA,
    providerA,
    bridgeBackBundle,
    'Bridge Lend Tokens Back'
  );

  // Check shadow account balance after bridge
  const shadowLendBalance = await lendToken.balanceOf(borrowerShadowAccount);
  console.log('Shadow account lend token balance on Chain A:', ethers.formatUnits(shadowLendBalance, 18));

  // =================================================================
  // STEP 7: Borrower Repays Loan Using Shadow Account
  // =================================================================
  console.log('\n========================================');
  console.log('STEP 7: BORROWER REPAYS LOAN (SHADOW ACCOUNT)');
  console.log('========================================');

  // Build approve calldata for repayment
  const approveRepayCalldata = lendToken.interface.encodeFunctionData('approve', [
    repoContractAddress,
    repaymentAmount,
  ]);

  // Build repayLoan calldata
  const repayLoanCalldata = repoContract.interface.encodeFunctionData('repayLoan', [offerId]);

  // Build bundle with shadow account calls
  const repayBundle = new BundleBuilder(chainAId)
    // First call: approve lend token for repayment via shadow account
    .addShadowAccountCall(lendTokenAddress, approveRepayCalldata)
    // Second call: repay loan via shadow account
    .addShadowAccountCall(repoContractAddress, repayLoanCalldata)
    .withUnbundler(walletA.address);

  const repayExecReceipt = await sendAndExecuteBundle(walletB, providerB, walletA, providerA, repayBundle, 'Repay Loan Bundle');

  // Check final offer status
  const offerAfterRepay = await repoContract.offers(offerId);
  console.log('Offer status after repay:', offerAfterRepay.status); // 2 = Completed

  // =================================================================
  // STEP 7b: FINALIZE COLLATERAL BRIDGE BACK TO CHAIN B
  // =================================================================
  console.log('\n--- Finalizing collateral bridge back to Chain B ---');

  // The repayLoan execution on chain A triggers a collateral transfer back to chain B
  const collateralBridgeBundles = extractBundlesFromReceipt(repayExecReceipt, chainAId);
  console.log(`Found ${collateralBridgeBundles.length} collateral bridge bundle(s) to finalize`);

  if (collateralBridgeBundles.length > 0) {
    for (const bundleInfo of collateralBridgeBundles) {
      console.log(`Finalizing collateral bridge bundle: ${bundleInfo.bundleHandle.bundleHash}`);
      const collateralBridgeReceipt = await finalizeAndExecuteBridgeBundle(
        providerA,
        walletB,
        bundleInfo,
        {
          gasLimit: 10_000_000n,
          gasPrice: 1_000_000_000n,
        }
      );
      console.log(`Collateral bridge bundle executed on chain B, tx: ${collateralBridgeReceipt.hash}`);
    }
  }

  // Get the bridged collateral token address on chain B and check balance
  const collateralTokenAddressOnB = await getBridgedTokenAddress(chainAId, collateralTokenAddress, providerB);
  console.log('Collateral token address on Chain B:', collateralTokenAddressOnB);

  const collateralTokenOnB = new ethers.Contract(collateralTokenAddressOnB, ERC20Abi, providerB);
  const borrowerCollateralBalance = await collateralTokenOnB.balanceOf(walletB.address);
  console.log('Borrower collateral token balance on Chain B:', ethers.formatUnits(borrowerCollateralBalance, 18));

  // =================================================================
  // SUMMARY
  // =================================================================
  console.log('\n========================================');
  console.log('DEMO COMPLETE!');
  console.log('========================================');
  console.log('Summary:');
  console.log('- RepoContract deployed on Chain A:', repoContractAddress);
  console.log('- Lend Token on Chain A:', lendTokenAddress);
  console.log('- Lend Token on Chain B:', lendTokenAddressOnB);
  console.log('- Collateral Token on Chain A:', collateralTokenAddress);
  console.log('- Collateral Token on Chain B:', collateralTokenAddressOnB);
  console.log('- Offer ID:', offerId.toString());
  console.log('- Final status:', offerAfterRepay.status === 2n ? 'Completed' : offerAfterRepay.status);
  console.log('\nThe demo successfully demonstrated:');
  console.log('1. Deploying RepoContract and ERC20 tokens on Chain A');
  console.log('2. Lender creating an offer on Chain A');
  console.log('3. Borrower from Chain B accepting offer using shadow account');
  console.log('4. Finalizing token bridge to deliver lend tokens on Chain B');
  console.log('5. Bridging lend tokens back from Chain B to Chain A for repayment');
  console.log('6. Borrower repaying loan using shadow account');
  console.log('7. Finalizing collateral bridge back to Chain B');
}

main().catch((err) => {
  console.error('Error:', err);
  process.exit(1);
});
